async function activateReferral(userId){if(!pool||!userId)return;const client=await pool.connect();try{await client.query("BEGIN");const invited=(await client.query("SELECT id,referred_by,referral_activated_at FROM users WHERE id=$1 FOR UPDATE",[userId])).rows[0];if(!invited||!invited.referred_by||invited.referral_activated_at){await client.query("ROLLBACK");return}await client.query("SELECT id FROM users WHERE id=$1 FOR UPDATE",[invited.referred_by]);await client.query("UPDATE users SET referral_activated_at=NOW() WHERE id=$1",[userId]);const n=Number((await client.query("SELECT COUNT(*) n FROM users WHERE referred_by=$1 AND referral_activated_at IS NOT NULL",[invited.referred_by])).rows[0].n);let reward="",title="",body="";if(n===1){const r=await client.query("INSERT INTO referral_rewards(referrer_id,referred_id,milestone,reward) VALUES($1,$2,1,'boost') ON CONFLICT(referred_id) DO NOTHING RETURNING id",[invited.referred_by,userId]);if(r.rows.length){await client.query("UPDATE users SET referral_boost_credits=COALESCE(referral_boost_credits,0)+1 WHERE id=$1",[invited.referred_by]);reward="boost";title="Referral reward";body="You earned 1 free Boost."}}else if(n===2||n===3){const days=n===2?7:30,code=n===2?"plus_7d":"plus_30d";const r=await client.query("INSERT INTO referral_rewards(referrer_id,referred_id,milestone,reward) VALUES($1,$2,$3,$4) ON CONFLICT(referred_id) DO NOTHING RETURNING id",[invited.referred_by,userId,n,code]);if(r.rows.length){await client.query("UPDATE users SET referral_plus_days=COALESCE(referral_plus_days,0)+$1 WHERE id=$2",[days,invited.referred_by]);reward=code;title="Referral reward";body="You earned "+days+" days of NOW Plus."}}if(reward)await client.query("INSERT INTO notifications(user_id,type,title,body) VALUES($1,'referral_reward',$2,$3)",[invited.referred_by,title,body]);await client.query("COMMIT")}catch(e){try{await client.query("ROLLBACK")}catch(_){}console.error("Referral activation:",e.message)}finally{client.release()}}

