const rateBuckets=new Map();function rateOk(req,limit=120){const ip=String(req.headers['x-forwarded-for']||req.socket.remoteAddress||'').split(',')[0].trim(),minute=Math.floor(Date.now()/60000),key=ip+':'+minute,n=(rateBuckets.get(key)||0)+1;rateBuckets.set(key,n);if(rateBuckets.size>5000)for(const k of rateBuckets.keys())if(!k.endsWith(':'+minute))rateBuckets.delete(k);return n<=limit}
async function moderatePublic(value){const text=String(value||'').trim();if(!text)return;if(!OPENAI_API_KEY)throw new Error('Moderation temporarily unavailable');const signal=AbortSignal.timeout(8000);let response;try{response=await fetch('https://api.openai.com/v1/moderations',{method:'POST',headers:{Authorization:'Bearer '+OPENAI_API_KEY,'Content-Type':'application/json'},body:JSON.stringify({model:'omni-moderation-latest',input:text.slice(0,6000)}),signal})}catch(e){throw new Error('Moderation temporarily unavailable')}if(!response.ok)throw new Error('Moderation temporarily unavailable');const data=await response.json();if(!data.results?.length)throw new Error('Moderation temporarily unavailable');if(data.results[0].flagged)throw new Error('Content is not allowed')}
function moderatorAuthorized(req){const secret=process.env.NOW_MODERATOR_TOKEN||'',given=String(req.headers.authorization||'').replace(/^Bearer\s+/i,'');if(!secret||!given)return false;const a=Buffer.from(secret),b=Buffer.from(given);return a.length===b.length&&crypto.timingSafeEqual(a,b)}
